import sqlite3
from datetime import datetime, timezone

DATABASE_PATH = "workspace.db"


def archive_channel_and_transfer_ownership(channel_id: str, new_owner_user_id: str) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    database_cursor = database_connection.cursor()

    try:
        channel_row_found = database_cursor.execute(
            "SELECT id, name FROM channels WHERE id = ?", (channel_id,)
        ).fetchone()
        if channel_row_found is None:
            return {"status": "error", "message": "channel not found"}

        new_owner_row_found = database_cursor.execute(
            "SELECT id FROM users WHERE id = ? AND active = 1", (new_owner_user_id,)
        ).fetchone()
        if new_owner_row_found is None:
            return {"status": "error", "message": "new owner not found or inactive"}

        archive_timestamp_string = datetime.now(timezone.utc).isoformat()

        database_cursor.execute(
            "INSERT INTO archived_messages (id, channel_id, author_id, body, created_at, archived_at) "
            "SELECT id, channel_id, author_id, body, created_at, ? FROM messages WHERE channel_id = ?",
            (archive_timestamp_string, channel_id),
        )
        number_of_messages_moved = database_cursor.rowcount

        database_cursor.execute("DELETE FROM messages WHERE channel_id = ?", (channel_id,))
        database_cursor.execute("DELETE FROM channel_members WHERE channel_id = ?", (channel_id,))
        database_cursor.execute("DELETE FROM channels WHERE id = ?", (channel_id,))

        database_cursor.execute(
            "INSERT INTO archive_owners (channel_id, channel_name, owner_id, assigned_at) "
            "VALUES (?, ?, ?, ?)",
            (channel_id, channel_row_found["name"], new_owner_user_id, archive_timestamp_string),
        )

        database_connection.commit()
        return {
            "status": "ok",
            "channel_id": channel_id,
            "messages_archived": number_of_messages_moved,
            "archive_owner": new_owner_user_id,
        }
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return {"status": "error", "message": str(database_error)}
    finally:
        database_connection.close()

import sqlite3


def purge_expired_direct_messages(conversation_id: str, older_than_days: int) -> dict:
    if not conversation_id or not conversation_id.strip():
        return {"error": "conversation_id is required"}
    if older_than_days < 1:
        return {"error": "older_than_days must be at least 1"}
    connection = sqlite3.connect("workspace.db")
    cutoff_modifier = "-%d days" % older_than_days
    matching_rows = connection.execute(
        "SELECT id FROM direct_messages WHERE conversation_id = ? AND created_at < datetime('now', ?)",
        (conversation_id, cutoff_modifier),
    ).fetchall()
    if not matching_rows:
        connection.close()
        return {"found": 0, "deleted": 0}
    connection.executemany("DELETE FROM direct_messages WHERE id = ?", matching_rows)
    connection.commit()
    connection.close()
    return {"found": len(matching_rows), "deleted": len(matching_rows)}
